import type { Trait } from '../../trait/types';
import type { Modifier } from '../types';
import { createModifier } from '../modifier';

export const Not = <T extends Trait[] = Trait[]>(...traits: T): Modifier<T, 'not'> => {
    return createModifier('not', 1, traits);
};

import type { Trait } from '../../trait/types';
import type { Modifier, OrModifier, OrParameter } from '../types';
import { $modifier, createModifier } from '../modifier';

export const Or = <T extends OrParameter[]>(...params: T): OrModifier<T> => {
    // Separate traits from nested modifiers
    const traits: Trait[] = [];
    const modifiers: Modifier[] = [];

    for (const param of params) {
        if ((param as Modifier)[$modifier]) {
            modifiers.push(param as Modifier);
        } else {
            traits.push(param as Trait);
        }
    }

    const modifier = createModifier('or', 2, traits) as OrModifier<T>;
    modifier.modifiers = modifiers;

    return modifier;
};

import { $internal } from '../../common';
import type { Entity } from '../../entity/types';
import { getEntityId } from '../../entity/utils/pack-entity';
import type { World } from '../../world';
import type { QueryInstance } from '../types';

/**
 * Check if an entity matches a non-tracking query.
 * For tracking queries, use checkQueryTracking instead.
 */
export function checkQuery(world: World, query: QueryInstance, entity: Entity): boolean {
    const staticBitmasks = query.staticBitmasks;
    const generations = query.generations;
    const ctx = world[$internal];
    const eid = getEntityId(entity);

    if (query.traitInstances.all.length === 0) return false;

    for (let i = 0; i < generations.length; i++) {
        const generationId = generations[i];
        const bitmask = staticBitmasks[i];
        if (!bitmask) continue;

        const required = bitmask.required;
        const forbidden = bitmask.forbidden;
        const or = bitmask.or;
        const entityMask = ctx.entityMasks[generationId]?.[eid] || 0;

        if (!forbidden && !required && !or) return false;
        if (forbidden && (entityMask & forbidden) !== 0) return false;
        if (required && (entityMask & required) !== required) return false;
        if (or !== 0 && (entityMask & or) === 0) return false;
    }

    return true;
}

import { $internal } from '../../common';
import { Entity } from '../../entity/types';
import { getEntityId } from '../../entity/utils/pack-entity';
import { World } from '../../world';
import { EventType, QueryInstance } from '../types';

/**
 * Check if an entity matches a tracking query with event handling.
 *
 * PERF: This is a hot path - optimizations applied:
 * - Cache all property accesses at function start
 * - Use `| 0` instead of `|| 0` (bitwise coerces undefined to 0)
 * - Avoid optional chaining in inner loops
 * - Cache array references before mutation
 * - Early exits where possible
 */
export function checkQueryTracking(
    world: World,
    query: QueryInstance,
    entity: Entity,
    eventType: EventType,
    eventGenerationId: number,
    eventBitflag: number
): boolean {
    // Cache all property accesses upfront
    const staticBitmasks = query.staticBitmasks;
    const trackingGroups = query.trackingGroups;
    const generations = query.generations;
    const traitInstancesAll = query.traitInstances.all;
    const entityMasks = world[$internal].entityMasks;
    const eid = getEntityId(entity);

    const generationsLen = generations.length;
    const trackingGroupsLen = trackingGroups.length;

    // Early exit: no traits to check
    if (traitInstancesAll.length === 0) return false;

    // 1. Check static constraints (required/forbidden/or)
    for (let i = 0; i < generationsLen; i++) {
        const generationId = generations[i];
        const bitmask = staticBitmasks[i];
        if (!bitmask) continue;

        const required = bitmask.required;
        const forbidden = bitmask.forbidden;
        const or = bitmask.or;

        // PERF: Direct access + bitwise OR coerces undefined to 0
        const genMasks = entityMasks[generationId];
        const entityMask = genMasks ? (genMasks[eid] | 0) : 0;

        // Check forbidden traits
        if (forbidden && (entityMask & forbidden) !== 0) return false;

        // Check required traits
        if (required && (entityMask & required) !== required) return false;

        // Check Or traits
        if (or !== 0 && (entityMask & or) === 0) return false;
    }

    // 2. Process tracking groups - update trackers and check cross-event invalidation
    // Also track OR group state to avoid second loop when possible
    let hasOrGroup = false;
    let anyOrMatched = false;

    for (let i = 0; i < trackingGroupsLen; i++) {
        const group = trackingGroups[i];
        const groupType = group.type;
        const groupLogic = group.logic;
        const groupBitmasks = group.bitmasks;
        const groupBitmask = groupBitmasks[eventGenerationId];

        // Check if this event affects this group's traits
        if (groupBitmask && (groupBitmask & eventBitflag)) {
            // Cross-event invalidation:
            // - Remove event invalidates Added/Changed tracking
            // - Add event invalidates Removed/Changed tracking
            if (eventType === 'remove') {
                if (groupType === 'add' || groupType === 'change') return false;
            } else if (eventType === 'add') {
                if (groupType === 'remove' || groupType === 'change') return false;
            }

            // Update tracker if event type matches group type
            if (groupType === eventType) {
                // For change events, verify entity still has the trait
                if (eventType === 'change') {
                    const genMasks = entityMasks[eventGenerationId];
                    const entityMask = genMasks ? (genMasks[eid] | 0) : 0;
                    if (!(entityMask & eventBitflag)) return false;
                }

                // PERF: Cache tracker array reference before mutation
                const groupTrackers = group.trackers;
                let trackerArr = groupTrackers[eventGenerationId];
                if (!trackerArr) {
                    trackerArr = [];
                    groupTrackers[eventGenerationId] = trackerArr;
                }
                trackerArr[eid] = (trackerArr[eid] | 0) | eventBitflag;
            }
        }

        // 3. Verify tracking group satisfaction (merged into same loop)
        if (groupLogic === 'or') {
            hasOrGroup = true;
            if (!anyOrMatched) {
                // Check if any trait in OR group has been tracked
                const groupTrackers = group.trackers;
                const bitmaskLen = groupBitmasks.length;
                for (let genId = 0; genId < bitmaskLen; genId++) {
                    const mask = groupBitmasks[genId];
                    if (!mask) continue;
                    const trackerArr = groupTrackers[genId];
                    const tracker = trackerArr ? (trackerArr[eid] | 0) : 0;
                    if (tracker & mask) {
                        anyOrMatched = true;
                        break;
                    }
                }
            }
        } else {
            // AND group: all traits must be tracked
            const groupTrackers = group.trackers;
            const bitmaskLen = groupBitmasks.length;
            for (let genId = 0; genId < bitmaskLen; genId++) {
                const mask = groupBitmasks[genId];
                if (!mask) continue;
                const trackerArr = groupTrackers[genId];
                const tracker = trackerArr ? (trackerArr[eid] | 0) : 0;
                if ((tracker & mask) !== mask) {
                    return false;
                }
            }
        }
    }

    // If we have OR groups, at least one must match
    if (hasOrGroup && !anyOrMatched) {
        return false;
    }

    return true;
}

import { $internal } from '../../common';
import type { World } from '../../world';

// Some values are reserved.
// 0 - has
// 1 - not
// 2 - or
let cursor = 3;

export function createTrackingId() {
    return cursor++;
}

export function getTrackingCursor() {
    return cursor;
}

export function setTrackingMasks(world: World, id: number) {
    const ctx = world[$internal];
    const snapshot = structuredClone(ctx.entityMasks);
    ctx.trackingSnapshots.set(id, snapshot);

    // For dirty and changed masks, make clone of entity masks and set all bits to 0.
    ctx.dirtyMasks.set(
        id,
        snapshot.map((mask) => mask.map(() => 0))
    );

    ctx.changedMasks.set(
        id,
        snapshot.map((mask) => mask.map(() => 0))
    );
}

import { $internal } from '../../common';
import { isRelationPair } from '../../relation/utils/is-relation';
import type { Relation } from '../../relation/types';
import type { Trait } from '../../trait/types';
import { isModifier } from '../modifier';
import type { QueryHash, QueryParameter } from '../types';

const sortedIDs = new Float64Array(1024); // Use Float64 for larger IDs with relation encoding

export const createQueryHash = (parameters: QueryParameter[]): QueryHash => {
    sortedIDs.fill(0);
    let cursor = 0;

    for (let i = 0; i < parameters.length; i++) {
        const param = parameters[i];

        if (isRelationPair(param)) {
            // Encode relation pair as: (relationTraitId * 1000000) + targetId
            // This ensures unique hashes for different relation/target combinations
            const pairCtx = param[$internal];
            const relation = pairCtx.relation;
            const target = pairCtx.target;

            const relationId = (relation as Relation<Trait>)[$internal].trait.id;
            const targetId = typeof target === 'number' ? target : -1;

            // Combine into a unique hash number
            sortedIDs[cursor++] = relationId * 10000000 + targetId + 5000000;
        } else if (isModifier(param)) {
            const modifierId = param.id;
            const traitIds = param.traitIds;

            for (let i = 0; i < traitIds.length; i++) {
                const traitId = traitIds[i];
                sortedIDs[cursor++] = modifierId * 100000 + traitId;
            }
        } else {
            const traitId = (param as Trait).id;
            sortedIDs[cursor++] = traitId;
        }
    }

    // Sort only the portion of the array that has been filled.
    const filledArray = sortedIDs.subarray(0, cursor);
    filledArray.sort();

    // Create string key.
    const hash = filledArray.join(',');

    return hash;
};

import { $internal } from '../common';
import { createEntity, destroyEntity } from '../entity/entity';
import type { Entity } from '../entity/types';
import { createEntityIndex, getAliveEntities, isEntityAlive } from '../entity/utils/entity-index';
import { IsExcluded, createQueryInstance } from '../query/query';
import { createRelationOnlyQueryResult } from '../query/query-result';
import type { Query, QueryInstance, QueryParameter, QueryUnsubscriber } from '../query/types';
import { createQueryHash } from '../query/utils/create-query-hash';
import { isQuery } from '../query/utils/is-query';
import { getTrackingCursor, setTrackingMasks } from '../query/utils/tracking-cursor';
import { getEntitiesWithRelationTo } from '../relation/relation';
import type { Relation, RelationPair } from '../relation/types';
import { isRelation, isRelationPair } from '../relation/utils/is-relation';
import { addTrait, getTrait, hasTrait, registerTrait, removeTrait, setTrait } from '../trait/trait';
import { clearTraitInstance, getTraitInstance, hasTraitInstance } from '../trait/trait-instance';
import type {
    ConfigurableTrait,
    ExtractSchema,
    SetTraitCallback,
    Trait,
    TraitRecord,
    TraitValue,
} from '../trait/types';
import { universe } from '../universe/universe';
import type { World, WorldInternal, WorldOptions } from './types';
import { allocateWorldId, releaseWorldId } from './utils/world-index';

export function createWorld(options: WorldOptions): World;
export function createWorld(...traits: ConfigurableTrait[]): World;
export function createWorld(
    optionsOrFirstTrait?: WorldOptions | ConfigurableTrait,
    ...traits: ConfigurableTrait[]
): World {
    const id = allocateWorldId(universe.worldIndex);
    let isInitialized = false;
    let lazyTraits: ConfigurableTrait[] | undefined;
    type HookInput = Trait | Relation<Trait> | RelationPair<Trait>;
    type HookCallback = (entity: Entity, target?: Entity) => void;

    function resolveHookTrait(input: HookInput): Trait {
        if (isRelationPair(input)) return input[$internal].relation[$internal].trait;
        if (isRelation(input)) return input[$internal].trait;
        return input;
    }

    function resolveHookCallback(input: HookInput, callback: HookCallback): HookCallback {
        if (isRelationPair(input)) {
            const pairTarget = input[$internal].target;
            if (pairTarget === '*') return callback;
            return (entity: Entity, target?: Entity) => {
                if (target === pairTarget) callback(entity, target);
            };
        }
        return callback;
    }

    const world = {
        [$internal]: {
            entityIndex: createEntityIndex(id),
            entityMasks: [[]],
            entityTraits: new Map(),
            bitflag: 1,
            traitInstances: [],
            relations: new Set(),
            queriesHashMap: new Map(),
            queryInstances: [],
            actionInstances: [],
            notQueries: new Set(),
            dirtyQueries: new Set(),
            dirtyMasks: new Map(),
            trackingSnapshots: new Map(),
            changedMasks: new Map(),
            worldEntity: null!,
            trackedTraits: new Set(),
            resetSubscriptions: new Set(),
        } as WorldInternal,

        traits: new Set<Trait>(),

        init(...initTraits: ConfigurableTrait[]) {
            const ctx = world[$internal];
            if (isInitialized) return;

            isInitialized = true;
            universe.worlds[id] = world;

            // Create uninitialized added masks.
            const cursor = getTrackingCursor();
            for (let i = 0; i < cursor; i++) {
                setTrackingMasks(world, i);
            }

            // Register system traits.
            if (!hasTraitInstance(ctx.traitInstances, IsExcluded)) registerTrait(world, IsExcluded);

            // Check for traits passed into lazy init
            if (lazyTraits) {
                initTraits = lazyTraits;
                // clear lazyTraits
                lazyTraits = undefined;
            }
            // Create world entity.
            ctx.worldEntity = createEntity(world, IsExcluded, ...initTraits);
        },

        spawn(...spawnTraits: ConfigurableTrait[]): Entity {
            return createEntity(world, ...spawnTraits);
        },

        has(target: Entity | Trait): boolean {
            return typeof target === 'number'
                ? isEntityAlive(world[$internal].entityIndex, target)
                : hasTrait(world, world[$internal].worldEntity, target);
        },

        add(...addTraits: ConfigurableTrait[]) {
            addTrait(world, world[$internal].worldEntity, ...addTraits);
        },

        remove(...removeTraits: Trait[]) {
            removeTrait(world, world[$internal].worldEntity, ...removeTraits);
        },

        get<T extends Trait>(trait: T): TraitRecord<ExtractSchema<T>> | undefined {
            return getTrait(world, world[$internal].worldEntity, trait);
        },

        set<T extends Trait>(trait: T, value: TraitValue<ExtractSchema<T>> | SetTraitCallback<T>) {
            setTrait(world, world[$internal].worldEntity, trait, value, true);
        },

        destroy() {
            // Destroy world entity.
            destroyEntity(world, world[$internal].worldEntity);
            world[$internal].worldEntity = null!;

            world.reset();
            isInitialized = false;
            // Clean up universe side effects.
            releaseWorldId(universe.worldIndex, id);
            universe.worlds[id] = null;
        },

        reset() {
            lazyTraits = undefined;
            const ctx = world[$internal];

            // Destroy all entities so any cleanup is done.
            world.entities.forEach((entity) => {
                // Some relations may have caused the entity to be destroyed before
                // we get to them in the loop.
                if (world.has(entity)) {
                    destroyEntity(world, entity);
                }
            });

            ctx.entityIndex = createEntityIndex(id);
            ctx.entityTraits.clear();
            ctx.entityMasks = [[]];
            ctx.bitflag = 1;

            clearTraitInstance(ctx.traitInstances);
            world.traits.clear();
            ctx.relations.clear();

            ctx.queriesHashMap.clear();
            ctx.queryInstances.length = 0;
            ctx.actionInstances.length = 0;
            ctx.dirtyQueries.clear();
            ctx.notQueries.clear();

            ctx.trackingSnapshots.clear();
            ctx.dirtyMasks.clear();
            ctx.changedMasks.clear();
            ctx.trackedTraits.clear();

            // Create new world entity.
            ctx.worldEntity = createEntity(world, IsExcluded);

            for (const sub of ctx.resetSubscriptions) {
                sub(world);
            }
        },

        query(...args: any[]) {
            const ctx = world[$internal];

            // Check if first arg is a QueryRef
            if (args.length === 1 && isQuery(args[0])) {
                const queryRef = args[0];
                // Try array lookup first
                let query = ctx.queryInstances[queryRef.id];
                if (query) return query.run(world, queryRef.parameters);

                // Fallback to hash map
                query = ctx.queriesHashMap.get(queryRef.hash);
                if (!query) {
                    query = createQueryInstance(world, queryRef.parameters);
                    ctx.queriesHashMap.set(queryRef.hash, query);
                    // Store in array for fast future lookups
                    if (queryRef.id >= ctx.queryInstances.length) {
                        ctx.queryInstances.length = queryRef.id + 1;
                    }
                    ctx.queryInstances[queryRef.id] = query;
                }
                return query.run(world, queryRef.parameters);
            } else {
                const params = args as QueryParameter[];

                // Fast path: single relation pair with specific target
                if (params.length === 1 && isRelationPair(params[0])) {
                    const pairCtx = params[0][$internal];
                    const relation = pairCtx.relation;
                    const target = pairCtx.target;

                    // Only use fast path for specific targets
                    if (typeof target === 'number') {
                        const entities = getEntitiesWithRelationTo(
                            world,
                            relation as Relation<Trait>,
                            target as Entity
                        );
                        return createRelationOnlyQueryResult(entities.slice() as Entity[]);
                    }
                }

                const hash = createQueryHash(params);
                let query = ctx.queriesHashMap.get(hash);

                if (!query) {
                    query = createQueryInstance(world, params);
                    ctx.queriesHashMap.set(hash, query);
                }

                return query.run(world, params);
            }
        },

        queryFirst(...args: [string] | QueryParameter[]) {
            // @ts-expect-error - Having an issue with the TS overloads.
            return world.query(...args)[0];
        },

        onQueryAdd(
            args: Query<QueryParameter[]> | QueryParameter[],
            callback: (entity: Entity) => void
        ): QueryUnsubscriber {
            const ctx = world[$internal];
            let query: QueryInstance;

            // Check if args is a QueryRef object
            if (isQuery(args)) {
                const queryRef = args;
                query = ctx.queryInstances[queryRef.id] || ctx.queriesHashMap.get(queryRef.hash)!;

                if (!query) {
                    query = createQueryInstance(world, queryRef.parameters);
                    ctx.queriesHashMap.set(queryRef.hash, query);
                    if (queryRef.id >= ctx.queryInstances.length) {
                        ctx.queryInstances.length = queryRef.id + 1;
                    }
                    ctx.queryInstances[queryRef.id] = query;
                }
            } else {
                const hash = createQueryHash(args as QueryParameter[]);
                query = ctx.queriesHashMap.get(hash)!;

                if (!query) {
                    query = createQueryInstance(world, args as QueryParameter[]);
                    ctx.queriesHashMap.set(hash, query);
                }
            }

            query.addSubscriptions.add(callback);

            return () => query.addSubscriptions.delete(callback);
        },

        onQueryRemove(
            args: Query<QueryParameter[]> | QueryParameter[],
            callback: (entity: Entity) => void
        ): QueryUnsubscriber {
            const ctx = world[$internal];
            let query: QueryInstance;

            // Check if args is a QueryRef object
            if (isQuery(args)) {
                const queryRef = args;
                query = ctx.queryInstances[queryRef.id] || ctx.queriesHashMap.get(queryRef.hash)!;

                if (!query) {
                    query = createQueryInstance(world, queryRef.parameters);
                    ctx.queriesHashMap.set(queryRef.hash, query);
                    if (queryRef.id >= ctx.queryInstances.length) {
                        ctx.queryInstances.length = queryRef.id + 1;
                    }
                    ctx.queryInstances[queryRef.id] = query;
                }
            } else {
                const hash = createQueryHash(args as QueryParameter[]);
                query = ctx.queriesHashMap.get(hash)!;

                if (!query) {
                    query = createQueryInstance(world, args as QueryParameter[]);
                    ctx.queriesHashMap.set(hash, query);
                }
            }

            query.removeSubscriptions.add(callback);

            return () => query.removeSubscriptions.delete(callback);
        },

        onAdd<T extends Trait>(
            trait: T | Relation<T> | RelationPair<T>,
            callback: (entity: Entity, target?: Entity) => void
        ): QueryUnsubscriber {
            const ctx = world[$internal];
            const resolvedTrait = resolveHookTrait(trait);
            const resolvedCallback = resolveHookCallback(trait, callback);

            let data = getTraitInstance(ctx.traitInstances, resolvedTrait);

            if (!data) {
                registerTrait(world, resolvedTrait);
                data = getTraitInstance(ctx.traitInstances, resolvedTrait)!;
            }

            data.addSubscriptions.add(resolvedCallback);

            return () => data.addSubscriptions.delete(resolvedCallback);
        },

        onRemove<T extends Trait>(
            trait: T | Relation<T> | RelationPair<T>,
            callback: (entity: Entity, target?: Entity) => void
        ): QueryUnsubscriber {
            const ctx = world[$internal];
            const resolvedTrait = resolveHookTrait(trait);
            const resolvedCallback = resolveHookCallback(trait, callback);

            let data = getTraitInstance(ctx.traitInstances, resolvedTrait);

            if (!data) {
                registerTrait(world, resolvedTrait);
                data = getTraitInstance(ctx.traitInstances, resolvedTrait)!;
            }

            data.removeSubscriptions.add(resolvedCallback);

            return () => data.removeSubscriptions.delete(resolvedCallback);
        },

        onChange(
            trait: Trait | Relation<Trait> | RelationPair<Trait>,
            callback: (entity: Entity, target?: Entity) => void
        ) {
            const ctx = world[$internal];
            const resolvedTrait = resolveHookTrait(trait);
            const resolvedCallback = resolveHookCallback(trait, callback);

            if (!hasTraitInstance(ctx.traitInstances, resolvedTrait))
                registerTrait(world, resolvedTrait);

            const data = getTraitInstance(ctx.traitInstances, resolvedTrait)!;
            data.changeSubscriptions.add(resolvedCallback);

            ctx.trackedTraits.add(resolvedTrait);

            return () => {
                data.changeSubscriptions.delete(resolvedCallback);
                if (data.changeSubscriptions.size === 0) ctx.trackedTraits.delete(resolvedTrait);
            };
        },
    } as World;

    // Read-only properties via getters
    Object.defineProperty(world, 'id', {
        get: () => id,
        enumerable: true,
    });
    Object.defineProperty(world, 'isInitialized', {
        get: () => isInitialized,
        enumerable: true,
    });
    Object.defineProperty(world, 'entities', {
        get: () => getAliveEntities(world[$internal].entityIndex),
        enumerable: true,
    });

    // Handle initialization based on arguments
    if (
        optionsOrFirstTrait &&
        typeof optionsOrFirstTrait === 'object' &&
        !Array.isArray(optionsOrFirstTrait)
    ) {
        const { traits: optionTraits = [], lazy = false } = optionsOrFirstTrait as WorldOptions;
        if (!lazy) {
            world.init(...optionTraits);
        } else {
            lazyTraits = optionTraits;
        }
    } else {
        world.init(...(optionsOrFirstTrait ? [optionsOrFirstTrait, ...traits] : traits));
    }

    return world;
}

import { ActionInstance } from '../actions/types';
import type { $internal } from '../common';
import type { Entity } from '../entity/types';
import type { createEntityIndex } from '../entity/utils/entity-index';
import type {
    Query,
    QueryInstance,
    QueryParameter,
    QueryResult,
    QueryUnsubscriber,
} from '../query/types';
import type { Relation, RelationPair } from '../relation/types';
import type {
    ConfigurableTrait,
    ExtractSchema,
    SetTraitCallback,
    Trait,
    TraitInstance,
    TraitRecord,
    TraitValue,
} from '../trait/types';

export type WorldOptions = {
    traits?: ConfigurableTrait[];
    lazy?: boolean;
};

export type WorldInternal = {
    entityIndex: ReturnType<typeof createEntityIndex>;
    entityMasks: number[][];
    entityTraits: Map<number, Set<Trait>>;
    bitflag: number;
    traitInstances: (TraitInstance | undefined)[];
    relations: Set<Relation<Trait>>;
    queriesHashMap: Map<string, QueryInstance>;
    queryInstances: (QueryInstance | undefined)[];
    actionInstances: (ActionInstance | undefined)[];
    notQueries: Set<QueryInstance>;
    dirtyQueries: Set<QueryInstance>;
    dirtyMasks: Map<number, number[][]>;
    trackingSnapshots: Map<number, number[][]>;
    changedMasks: Map<number, number[][]>;
    worldEntity: Entity;
    trackedTraits: Set<Trait>;
    resetSubscriptions: Set<(world: World) => void>;
};

export type World = {
    readonly id: number;
    readonly isInitialized: boolean;
    readonly entities: Entity[];
    readonly traits: Set<Trait>;
    [$internal]: WorldInternal;
    init(...traits: ConfigurableTrait[]): void;
    spawn(...traits: ConfigurableTrait[]): Entity;
    has(entity: Entity): boolean;
    has(trait: Trait): boolean;
    has(target: Entity | Trait): boolean;
    add(...traits: ConfigurableTrait[]): void;
    remove(...traits: Trait[]): void;
    get<T extends Trait>(trait: T): TraitRecord<ExtractSchema<T>> | undefined;
    set<T extends Trait>(trait: T, value: TraitValue<ExtractSchema<T>> | SetTraitCallback<T>): void;
    destroy(): void;
    reset(): void;
    query<T extends QueryParameter[]>(key: Query<T>): QueryResult<T>;
    query<T extends QueryParameter[]>(...parameters: T): QueryResult<T>;
    queryFirst<T extends QueryParameter[]>(key: Query<T>): Entity | undefined;
    queryFirst<T extends QueryParameter[]>(...parameters: T): Entity | undefined;
    onQueryAdd<T extends QueryParameter[]>(
        key: Query<T>,
        callback: (entity: Entity) => void
    ): QueryUnsubscriber;
    onQueryAdd<T extends QueryParameter[]>(
        parameters: T,
        callback: (entity: Entity) => void
    ): QueryUnsubscriber;
    onQueryRemove<T extends QueryParameter[]>(
        key: Query<T>,
        callback: (entity: Entity) => void
    ): QueryUnsubscriber;
    onQueryRemove<T extends QueryParameter[]>(
        parameters: T,
        callback: (entity: Entity) => void
    ): QueryUnsubscriber;
    onAdd<T extends Trait>(trait: T, callback: (entity: Entity) => void): QueryUnsubscriber;
    onAdd<T extends Trait>(
        relation: Relation<T>,
        callback: (entity: Entity, target: Entity) => void
    ): QueryUnsubscriber;
    onAdd<T extends Trait>(
        pair: RelationPair<T>,
        callback: (entity: Entity, target: Entity) => void
    ): QueryUnsubscriber;
    onAdd(
        input: Trait | Relation<Trait> | RelationPair,
        callback: (entity: Entity, target?: Entity) => void
    ): QueryUnsubscriber;
    onRemove<T extends Trait>(trait: T, callback: (entity: Entity) => void): QueryUnsubscriber;
    onRemove<T extends Trait>(
        relation: Relation<T>,
        callback: (entity: Entity, target: Entity) => void
    ): QueryUnsubscriber;
    onRemove<T extends Trait>(
        pair: RelationPair<T>,
        callback: (entity: Entity, target: Entity) => void
    ): QueryUnsubscriber;
    onRemove(
        input: Trait | Relation<Trait> | RelationPair,
        callback: (entity: Entity, target?: Entity) => void
    ): QueryUnsubscriber;
    onChange<T extends Trait>(trait: T, callback: (entity: Entity) => void): QueryUnsubscriber;
    onChange<T extends Trait>(
        relation: Relation<T>,
        callback: (entity: Entity, target: Entity) => void
    ): QueryUnsubscriber;
    onChange<T extends Trait>(
        pair: RelationPair<T>,
        callback: (entity: Entity, target: Entity) => void
    ): QueryUnsubscriber;
    onChange(
        input: Trait | Relation<Trait> | RelationPair,
        callback: (entity: Entity, target?: Entity) => void
    ): QueryUnsubscriber;
};

// This shallow equal looks insane because it is optimized to use short circuiting
// and the least amount of evaluations possible.

export function /* @inline @pure */ shallowEqual(obj1: any, obj2: any): boolean {
    return (
        obj1 === obj2 ||
        (typeof obj1 === 'object' &&
            obj1 !== null &&
            typeof obj2 === 'object' &&
            obj2 !== null &&
            (() => {
                const keys1 = Object.keys(obj1);
                const keys2 = Object.keys(obj2);
                return (
                    keys1.length === keys2.length &&
                    keys1.every((key) => Object.hasOwn(obj2, key) && obj1[key] === obj2[key])
                );
            })())
    );
}
